function agentModelDetailsForOffering(offering, available = true) {
  const canonicalModel = builtinCatalog.models.find((candidate) => candidate.id === offering.canonicalModelId);
  const languageOperation = offering.operations.find((operation) => operation.operation === "language.generate" && operation.enabled);
  const languageFeatures = new Set(languageOperation?.features ?? []);
  const supportedMediaTypes = Object.entries(mediaTypesByFeature).flatMap(([feature, mediaTypes]) => languageFeatures.has(feature) ? [...mediaTypes] : []);
  return {
    modelName: offering.id,
    model: canonicalModel?.name ?? offering.id,
    think: languageFeatures.has("thinking"),
    canonicalModelId: offering.canonicalModelId,
    offeringId: offering.id,
    providerId: offering.providerId,
    available,
    acceptsAttachments: supportedMediaTypes.length > 0,
    acceptsImages: languageFeatures.has("image_input"),
    supportedMediaTypes,
    supportsGrounding: languageFeatures.has("grounding"),
    filesUpload: offering.operations.some((operation) => operation.operation === "files.upload" && operation.enabled),
    maximumAttachments: 20,
    maximumAttachmentBytes: 64 * 1024 * 1024,
    lifecycle: offering.lifecycle
  };
}
