// apps/server/src/providers/catalog/agentModelSelection.ts
function normalizeAgentModelSelection(input) {
  const offering = builtinCatalog.offerings.find((candidate) => candidate.id === input.modelName);
  if (!offering)
    return input;
  const languageEnabled = offering.operations.some((operation) => operation.operation === "language.generate" && operation.enabled);
  if (!languageEnabled)
    throw new AgentModelSelectionError("agent.model_operation_unsupported");
  if (offering.support.implementation !== "implemented") {
    throw new AgentModelSelectionError("agent.model_not_implemented");
  }
  const canonicalModel = builtinCatalog.models.find((candidate) => candidate.id === offering.canonicalModelId);
  if (!canonicalModel)
    throw new AgentModelSelectionError("agent.canonical_model_missing");
  return {
    modelName: offering.id,
    model: canonicalModel.name,
    vendorId: offering.providerId
  };
}
var AgentModelSelectionError;
