// apps/server/src/security/credentials/legacyInputPolicy.ts
function sanitizeLegacyVendorInputResponse(inputs, values) {
  const passwordKeys = new Set(inputs.filter((input) => input.type === "password").map((input) => input.key));
  return Object.fromEntries(Object.entries(values).map(([key, value]) => [key, passwordKeys.has(key) ? "" : value]));
}
function validateLegacyVendorInputUpdate(inputs, values) {
  const passwordKeys = new Set(inputs.filter((input) => input.type === "password").map((input) => input.key));
  for (const key of passwordKeys) {
    if (values[key]?.trim())
      throw new Error("credential.rest_write_forbidden");
  }
  return Object.fromEntries(Object.entries(values).filter(([key]) => !passwordKeys.has(key)));
}

