class WorkbenchAssetIngestService {
  #database;
  #repository;
  #readFile;
  constructor(input) {
    this.#database = input.database;
    this.#repository = input.repository;
    this.#readFile = input.readFile;
  }
  async ingest(input) {
    if (input.items.length > 12)
      throw new Error("asset.maximum_items_exceeded");
    const seen = new Set;
    const result = [];
    for (const item of input.items) {
      const sourceIdentity = `${item.source}:${item.id}`;
      if (seen.has(sourceIdentity))
        throw new Error("asset.duplicate_source");
      seen.add(sourceIdentity);
      const source2 = await this.#resolveSource(item.source, item.id);
      if (!source2?.filePath || Number(source2.projectId) !== input.projectId) {
        throw new Error("asset.source_not_found");
      }
      const bytes = await this.#readFile(source2.filePath);
      const stored = await this.#repository.ingestOwnedBytes({
        bytes,
        declaredKind: item.kind,
        principalId: input.principalId,
        projectId: input.projectId,
        sourceKind: item.source,
        sourceId: String(item.id),
        ...item.durationSeconds === undefined ? {} : { durationSeconds: item.durationSeconds }
      });
      result.push(this.#toResult(stored, item));
    }
    return result;
  }
  async#resolveSource(source2, id) {
    if (source2 === "storyboard") {
      return await this.#database("o_storyboard").where({ id }).select("filePath", "projectId").first();
    }
    return await this.#database("o_assets").leftJoin("o_image", "o_image.id", "o_assets.imageId").where("o_assets.id", id).select("o_image.filePath as filePath", "o_assets.projectId as projectId").first();
  }
  #toResult(stored, item) {
    return {
      assetId: stored.id,
      kind: item.kind,
      role: item.role,
      ...item.durationSeconds === undefined ? {} : { durationSeconds: item.durationSeconds },
      mimeType: stored.mimeType,
      byteLength: stored.byteLength,
      sha256: stored.sha256
    };
  }
}

