// apps/server/src/routes/v2/providers.ts
async function buildProviderCredentialStatus(vault, availability) {
  const runtimeAvailability = availability ? await availability.resolveAll() : [];
  const aggregateHealth = (providerId) => {
    const values = runtimeAvailability.flatMap((candidate) => {
      const offering = builtinCatalog.offerings.find((entry) => entry.id === candidate.offeringId);
      return offering?.providerId === providerId ? [candidate.health] : [];
    });
    if (values.every((health) => health === "unknown"))
      return "unknown";
    if (values.every((health) => health === "healthy"))
      return "healthy";
    if (values.every((health) => health === "unhealthy"))
      return "unhealthy";
    return "degraded";
  };
  return providerCredentialsResultSchema.parse({
    schemaVersion: "2.0.0",
    providers: await Promise.all(builtinCatalog.providers.map(async (provider) => ({
      providerId: provider.id,
      health: aggregateHealth(provider.id),
      slots: await Promise.all(provider.credentialSlots.map(async (descriptor) => ({
        slot: descriptor.slot,
        ...await vault.status({ providerId: provider.id, slot: descriptor.slot })
      })))
    })))
  });
}
