class ProviderHealthMonitor {
  #records = new Map;
  #now;
  #ttlMs;
  constructor(now = Date.now, ttlMs = 5 * 60 * 1000) {
    this.#now = now;
    this.#ttlMs = ttlMs;
  }
  record(snapshot) {
    const recorded = {
      ...snapshot,
      checkedAt: new Date(this.#now()).toISOString()
    };
    this.#records.set(snapshot.offeringId, recorded);
    return recorded;
  }
  invalidateProvider(providerId) {
    for (const [key, snapshot] of this.#records) {
      if (snapshot.providerId === providerId)
        this.#records.delete(key);
    }
  }
  get(offeringId) {
    const record2 = this.#records.get(offeringId);
    if (!record2?.checkedAt || this.#now() - Date.parse(record2.checkedAt) > this.#ttlMs) {
      return {
        providerId: record2?.providerId ?? "unknown",
        offeringId,
        providerModelId: record2?.providerModelId ?? "unknown",
        deploymentRegion: record2?.deploymentRegion ?? "unknown",
        health: "unknown",
        capabilitiesObserved: false,
        supportedOperations: [],
        revisionObserved: false
      };
    }
    return record2;
  }
}
var runtime4;
function configureProviderHealthRuntime(monitor = new ProviderHealthMonitor) {
  runtime4 = monitor;
  return monitor;
}

