async function assertAgentProviderFilesOwned(attachments, principalId) {
  const references = attachments.flatMap((attachment) => attachment.source.type === "provider_file" ? [
    {
      providerId: attachment.source.providerId,
      fileId: attachment.source.fileId
    }
  ] : []);
  if (references.length > 0) {
    await getProviderFileLedger().assertOwned(references, principalId);
  }
}
function agentSourceReference(source2) {
  if (!source2 || typeof source2 !== "object")
    return;
  const value = source2;
  if (value.type !== "source" || typeof value.id !== "string")
    return;
  if (value.sourceType === "url" && typeof value.url === "string") {
    let site;
    try {
      site = new URL(value.url).hostname;
    } catch {
      return;
    }
    return {
      id: value.id,
      reference: {
        title: typeof value.title === "string" ? value.title : value.url,
        type: "web",
        url: value.url,
        site
      }
    };
  }
  if (value.sourceType === "document" && typeof value.title === "string") {
    return {
      id: value.id,
      reference: {
        title: value.title,
        type: "document",
        ...typeof value.filename === "string" ? { content: value.filename } : {}
      }
    };
  }
  return;
}
function agentUserContent(text2, attachments) {
  const content = text2.trim() ? [{ type: "text", text: text2 }] : [];
  for (const attachment of attachments) {
    const data = attachment.source.type === "inline" ? { type: "data", data: attachment.source.dataBase64 } : {
      type: "reference",
      reference: { [attachment.source.providerId]: attachment.source.fileId }
    };
    content.push({
      type: "file",
      data,
      mediaType: attachment.mediaType,
      filename: attachment.filename,
      ...attachment.source.type === "inline" && attachment.detail ? { providerOptions: { toonflow: { imageDetail: attachment.detail } } } : {}
    });
  }
  return content;
}

