function buildMemPrompt(mem) {
  let memoryContext = "";
  if (mem.rag.length) {
    memoryContext += `[相关记忆]
${mem.rag.map((r2) => r2.content).join(`
`)}`;
  }
  if (mem.summaries.length) {
    if (memoryContext)
      memoryContext += `

`;
    memoryContext += `[历史摘要]
${mem.summaries.map((s2, i2) => `${i2 + 1}. ${s2.content}`).join(`
`)}`;
  }
  if (mem.shortTerm.length) {
    if (memoryContext)
      memoryContext += `

`;
    memoryContext += `[近期对话]
${mem.shortTerm.map((m2) => `${m2.role}: ${m2.content}`).join(`
`)}`;
  }
  return `## Memory
以下是你对用户的记忆，可作为参考但不要主动提及：
${memoryContext}`;
}
