function buildSkillPrompt(skills) {
  const skillEntries = skills.map((s2) => `  <skill>
    <name>${s2.name}</name>
    <description>${s2.description}</description>
  </skill>`).join(`
`);
  return `
<available_skills>
${skillEntries}
</available_skills>`;
}
async function useProductionSkills(artName, storyName) {
  const artWorkerPath = utils_default.getPath(["skills", "art_skills", artName, "driector_skills"]);
  const storyWorkerPath = utils_default.getPath(["skills", "story_skills", storyName, "driector_skills"]);
  const productionPath = utils_default.getPath(["skills", "production_skills"]);
  const skillList = [
    ...await scanSkills(artWorkerPath + "/*.md"),
    ...await scanSkills(storyWorkerPath + "/*.md"),
    ...await scanSkills(productionPath + "/*.md")
  ];
  const mainSkills = [];
  for (const skillPath of skillList) {
    if (!fs12.existsSync(skillPath))
      throw new Error(`主技能文件不存在: ${skillPath}`);
    const content = await fs12.promises.readFile(skillPath, "utf-8");
    const parsed = parseFrontmatter(content);
    mainSkills.push({ path: skillPath, ...parsed });
  }
  const res = {
    prompt: `## Skills
以下技能提供了专业任务的专用指令。
当任务与某个技能的描述匹配时，调用 activate_skill 工具并传入技能名称来加载完整指令。
${buildSkillPrompt(mainSkills)}`,
    tools: createSkillTools(mainSkills, {
      mainSkill: mainSkills,
      secondarySkills: [],
      tertiarySkills: []
    })
  };
  return res;
}

