async function consumeFullStream2(fullStream, initialMsg, syncMsg) {
  let msg = initialMsg;
  let text2 = msg.text();
  let thinking = null;
  let search = null;
  const sourceIds = new Set;
  let thinkTime = 0;
  let fullResponse = "";
  try {
    for await (const chunk of fullStream) {
      if (syncMsg) {
        const newMsg = syncMsg();
        if (newMsg !== msg) {
          msg = newMsg;
          text2 = msg.text();
        }
      }
      if (chunk.type === "reasoning-start") {
        thinkTime = Date.now();
        thinking = msg.thinking("思考中...");
      } else if (chunk.type === "reasoning-delta") {
        thinking?.append(chunk.text);
      } else if (chunk.type === "reasoning-end") {
        thinkTime = Date.now() - thinkTime;
        thinking?.updateTitle(`思考完毕（${(thinkTime / 1000).toFixed(1)} 秒）`);
        thinking?.complete();
        thinking = null;
      } else if (chunk.type === "text-delta") {
        text2.append(chunk.text);
        fullResponse += chunk.text;
      } else if (chunk.type === "source") {
        const source2 = agentSourceReference(chunk);
        if (source2 && !sourceIds.has(source2.id)) {
          sourceIds.add(source2.id);
          search ??= msg.search("搜索结果");
          search.addReference(source2.reference);
        }
      } else if (chunk.type === "error") {
        throw chunk.error;
      }
    }
    text2.complete();
    search?.complete();
    msg.complete();
  } catch (err) {
    thinking?.complete();
    search?.error();
    const errMsg = err?.message ?? String(err);
    text2.append(errMsg);
    text2.error();
    msg.error();
    throw err;
  }
  return fullResponse;
}
function removeAllXmlTags2(text2) {
  text2 = text2.replace(/<([a-zA-Z][\w-]*)(\s+[^>]*)?>([\s\S]*?)<\/\1>/g, "");
  text2 = text2.replace(/<([a-zA-Z][\w-]*)(\s+[^>]*)?\/>/g, "");
  text2 = text2.replace(/<\/?[a-zA-Z][\w-]*(\s+[^>]*)?>/g, "");
  return text2.trim();
}

