var defaultResizeOptions = {
  width: 256,
  height: 256,
  fit: "inside",
  withoutEnlargement: true
};
async function resizeImage(srcPath, dstPath, opts) {
  const { width, height, fit, withoutEnlargement } = { ...defaultResizeOptions, ...opts };
  await fs14.mkdir(path18.dirname(dstPath), { recursive: true });
  await sharp2(srcPath).resize(width, height, { fit, withoutEnlargement }).toFile(dstPath);
}
async function ensureThumbnail(originalPath, thumbnailPath, size) {
  if (fss.existsSync(thumbnailPath)) {
    return thumbnailPath;
  }
  if (!fss.existsSync(originalPath)) {
    return null;
  }
  try {
    if (size?.type === "percentage") {
      const meta4 = await sharp2(originalPath).metadata();
      if (!meta4.width || !meta4.height) {
        console.warn("[image] 无法获取原图尺寸:", originalPath);
        return null;
      }
      const pct = size.value / 100;
      const w = Math.round(meta4.width * pct);
      const h2 = Math.round(meta4.height * pct);
      await resizeImage(originalPath, thumbnailPath, { width: w, height: h2 });
    } else if (size?.type === "dimensions") {
      await resizeImage(originalPath, thumbnailPath, {
        width: size.width,
        height: size.height
      });
    } else {
      await resizeImage(originalPath, thumbnailPath);
    }
    console.info(`[${thumbnailPath}] 小图生成成功`);
    return thumbnailPath;
  } catch (e2) {
    console.warn("[image] 生成缩略图失败:", e2);
    return null;
  }
}

